var convexityItems = []edakit.Item{
	{KP: 3, Q: "Is half-perimeter wirelength, $\\max_i x_i - \\min_i x_i$, convex in the pin coordinates?",
		A: "Yes: a max of linear functions is convex, and so is minus a min", D: []string{"No, the min makes it concave", "Only for two-pin nets", "No, it is not continuous"},
		Why: "Max of affine functions is convex and $-\\min = \\max(-x_i)$ is also convex, so the sum is convex though not smooth."},
	{KP: 3, Q: "Which transformation turns a posynomial gate-sizing delay into a convex function?",
		A: "Substituting $x = e^u$ and taking the logarithm of the delay", D: []string{"Squaring every size", "Rounding sizes to integers", "Replacing sizes by their reciprocals only"},
		Why: "A posynomial in $e^{u}$ is a sum of exponentials of affine functions; its log is log-sum-exp, which is convex."},
	{KP: 3, Q: "A placement density penalty counts the overflow of bin area above capacity using cell positions with sharp bin edges. Is it convex in the positions?",
		A: "No: bin occupancy changes discontinuously and nonmonotonically with position", D: []string{"Yes, all penalties are convex", "Yes, because overflow is nonnegative", "Only in one dimension"},
		Why: "Density is a nonconvex, nonsmooth function of positions, which is why analytical placers smooth it (bell shapes or electrostatics) and accept local optima."},
	{KP: 3, Q: "f and g are convex. Which combination is guaranteed convex?",
		A: "$\\max(f, g)$", D: []string{"$f \\cdot g$", "$f - g$", "$\\min(f, g)$"},
		Why: "Pointwise max and nonnegative sums preserve convexity; products, differences and minima generally do not."},
	{KP: 3, Q: "The Hessian of a twice-differentiable f has a negative eigenvalue at some point. What can you conclude?",
		A: "f is not convex", D: []string{"f is concave", "f has a minimum there", "f is convex but not strictly"},
		Why: "Convexity of a twice-differentiable function needs a positive semidefinite Hessian everywhere; one negative eigenvalue anywhere rules it out."},
	{KP: 3, Q: "Quadratic wirelength $\\sum w_{ij}(x_i - x_j)^2$ with no fixed pads has a singular Hessian. Why?",
		A: "Shifting every cell by the same amount leaves the cost unchanged, so the all-ones vector is in the null space", D: []string{"The weights are negative", "Quadratic functions always have singular Hessians", "The problem is nonconvex"},
		Why: "The Hessian is the graph Laplacian, which is only semidefinite; fixed pads add diagonal terms that make it definite."},
	{KP: 3, Q: "Is the log-sum-exp wirelength model convex?",
		A: "Yes, log-sum-exp is convex and smooth", D: []string{"No, exponentials are nonconvex in sums", "Only when gamma is large", "Only for nets with two pins"},
		Why: "Log-sum-exp has a positive semidefinite Hessian everywhere, so smoothing HPWL this way keeps convexity."},
}

